  "privacy.headTitle": "ଗୋପନୀୟତା ନୀତି - {appName} |",
  "privacy.kicker": "DPDP ଅଧିନିୟମ 2023 ବିଧି ନିୟମ |",
  "privacy.title": "ଗୋପନୀୟତା ନୀତି",
  "privacy.lastUpdated": "ଶେଷ ଅଦ୍ୟତନ: ସେପ୍ଟେମ୍ବର 2026 • ଭାରତ ସରକାର ଜାତୀୟ ଡିଜିଟାଲ୍ ଭିତ୍ତିଭୂମି |",
  "privacy.section1.heading": "1। ବିଧିଗତ ପ୍ରତିବଦ୍ଧତା ଏବଂ ପରିସର |",
  "privacy.section2.heading": "2। ଆମେ ସଂଗ୍ରହ କରୁଥିବା ତଥ୍ୟ (ଡାଟା ମିନିମାଇଜେସନ୍ ର ନୀତି) |",
  "privacy.section3.heading": "3। ପ୍ରକ୍ରିୟାକରଣର ଉଦ୍ଦେଶ୍ୟ ଏବଂ ପ୍ରତ୍ୟକ୍ଷ ଦେୟ |",
  "privacy.section3.intro": "ସଂଗୃହିତ ତଥ୍ୟ କେବଳ ନିମ୍ନଲିଖିତ ସ୍ପଷ୍ଟ ଉଦ୍ଦେଶ୍ୟ ପାଇଁ ପ୍ରକ୍ରିୟାକରଣ କରାଯାଏ:",
  "privacy.section3.bullet1": "0% ପ୍ଲାଟଫର୍ମ ରିହାତି ସହିତ କାରିଗର ଗିଲ୍ଡମାନଙ୍କୁ ସିଧାସଳଖ DBT ବ୍ୟାଙ୍କ ଦେୟକୁ ସୁଗମ କରିବା |",
  "privacy.section3.bullet2": "ମେଣ୍ଟିଂ ଟ୍ୟାମ୍ପର୍-ପ୍ରୁଫ୍ କ୍ରିପ୍ଟୋଗ୍ରାଫିକ୍ Ed25519 ଡିଜିଟାଲ୍ ପ୍ରୋଭେନାନ୍ସ ସାର୍ଟିଫିକେଟ୍ |",
  "privacy.section3.bullet4": "SMS ଏବଂ ଇମେଲ ମାଧ୍ୟମରେ ପୂରଣ ଏବଂ ବିତରଣ ସ୍ଥିତି ବିଜ୍ଞପ୍ତି ନିଶ୍ଚିତ କରିବା |",
  "privacy.section4.heading": "4। ତୃତୀୟ-ପକ୍ଷ ତଥ୍ୟ ବିକ୍ରୟ ଉପରେ ସମ୍ପୂର୍ଣ୍ଣ ନିଷେଧ |",
  "privacy.section5.heading": "କ୍ରିପ୍ଟୋଗ୍ରାଫିକ୍ ସୁରକ୍ଷା ଏବଂ କୁକି ନୀତି |",
  "privacy.section6.heading": "6। ଡାଟା ବିଷୟ ଅଧିକାର ଏବଂ ଅଭିଯୋଗ ସମାଧାନ |",
