  "terms.headTitle": "ସେବା ସର୍ତ୍ତାବଳୀ - {appName} |",
  "terms.kicker": "ସରକାରୀ ଶାସନ ଏବଂ ଗିଲ୍ଡ ମାଣ୍ଡେଟ୍ |",
  "terms.title": "ସେବା ସର୍ତ୍ତାବଳୀ",
  "terms.lastUpdated": "ଶେଷ ଅଦ୍ୟତନ: ସେପ୍ଟେମ୍ବର 2026 • ସାମାଜିକ ନ୍ୟାୟ ଏବଂ ସଶକ୍ତିକରଣ ମନ୍ତ୍ରଣାଳୟ, ଭାରତ ସରକାର |",
  "terms.section1.heading": "ପ୍ଲାଟଫର୍ମ ମଣ୍ଡଳ ଏବଂ ଜନସାଧାରଣ ଭିତ୍ତିଭୂମି |",
  "terms.section2.heading": "2। ଭ ograph ଗୋଳିକ ସୂଚକାଙ୍କ (GI) ଏବଂ ପ୍ରାମାଣିକତା ମାନକ |",
  "terms.section3.heading": "3। 100% ସିଧାସଳଖ ଦେୟ ଏବଂ 0% ପ୍ଲାଟଫର୍ମ ରିହାତି |",
  "terms.section4.heading": "4। ମେଡ୍-ଟୁ-ଅର୍ଡର ଏବଂ ଅନୁଷ୍ଠାନିକ ପୂରଣ |",
  "terms.section5.heading": "5। ପାରମ୍ପାରିକ ସାଂସ୍କୃତିକ ଅଭିବ୍ୟକ୍ତିର ବ Intell ଦ୍ଧିକ ଗୁଣ |",
  "terms.section6.heading": "6। ବିବାଦର ସମାଧାନ ଏବଂ ଅଧିକାର",
